    "builder.allowLan": "\u0627\u062C\u0627\u0632\u0647\u200C\u06CC \u062F\u0633\u062A\u0631\u0633\u06CC LAN (\u06AF\u0648\u0634\u200C\u062F\u0627\u062F\u0646 \u0628\u0647 0.0.0.0)",
