    "builder.allowLanWarning": "\u0647\u0634\u062F\u0627\u0631 \u0627\u0645\u0646\u06CC\u062A\u06CC: \u0628\u0627 0.0.0.0 \u067E\u0631\u0627\u06A9\u0633\u06CC \u0645\u062D\u0644\u06CC SOCKS/HTTP \u0628\u062F\u0648\u0646 \u0627\u062D\u0631\u0627\u0632 \u0647\u0648\u06CC\u062A \u062F\u0631 \u062F\u0633\u062A\u0631\u0633 \u0647\u0645\u0647\u200C\u06CC \u062F\u0633\u062A\u06AF\u0627\u0647\u200C\u0647\u0627\u06CC \u0634\u0628\u06A9\u0647\u200C\u062A\u0627\u0646 \u0627\u0633\u062A \u2014 \u0647\u0631 \u06A9\u0633\u06CC \u062F\u0631 \u0647\u0645\u0627\u0646 LAN \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u062A\u0631\u0627\u0641\u06CC\u06A9\u0634 \u0631\u0627 \u0627\u0632 \u0645\u0627\u0634\u06CC\u0646 \u0634\u0645\u0627 \u0639\u0628\u0648\u0631 \u062F\u0647\u062F \u0648 \u0627\u0632 IP \u062E\u0631\u0648\u062C\u06CC \u0634\u0645\u0627 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u062F. \u0641\u0642\u0637 \u062F\u0631 \u0634\u0628\u06A9\u0647\u200C\u06CC \u0645\u0648\u0631\u062F \u0627\u0639\u062A\u0645\u0627\u062F \u0641\u0639\u0627\u0644 \u06A9\u0646\u06CC\u062F.",
    "builder.mux": "\u0686\u0646\u062F\u06AF\u0627\u0646\u0647\u200C\u0633\u0627\u0632\u06CC Mux (\u0647\u0645\u0632\u0645\u0627\u0646\u06CC \u06F8)",
    "builder.muxHint": "vmess/vless/trojan\u061B \u0628\u0631\u0627\u06CC \u0641\u0644\u0648\u0647\u0627\u06CC XTLS vision \u062E\u0648\u062F\u06A9\u0627\u0631 \u0631\u062F \u0645\u06CC\u200C\u0634\u0648\u062F\u061B \u067E\u0631\u0648\u062A\u06A9\u0644\u200C\u0647\u0627\u06CC sing-box \u0628\u06CC\u200C\u062A\u0623\u062B\u06CC\u0631\u0646\u062F",
    "builder.fragment": "\u0642\u0637\u0639\u0647\u200C\u0642\u0637\u0639\u0647\u200C\u0633\u0627\u0632\u06CC TLS (\u0636\u062F DPI)",
    "builder.fragmentHint": "TLS ClientHello \u0631\u0627 \u0628\u0647 \u0642\u0637\u0639\u0627\u062A \u06A9\u0648\u0686\u06A9 \u0645\u06CC\u200C\u0634\u06A9\u0646\u062F (\u0641\u0642\u0637 \u06A9\u0627\u0646\u0641\u06CC\u06AF\u200C\u0647\u0627\u06CC tls/reality \u0647\u0633\u062A\u0647\u200C\u06CC Xray). \u067E\u0631\u0648\u062A\u06A9\u0644\u200C\u0647\u0627\u06CC sing-box \u0645\u0628\u062A\u0646\u06CC \u0628\u0631 QUIC \u0647\u0633\u062A\u0646\u062F \u0648 \u0628\u06CC\u200C\u062A\u0623\u062B\u06CC\u0631\u0646\u062F\u061B Aether \u06A9\u0644\u06CC\u062F \u062E\u0648\u062F\u0634 \u0631\u0627 \u062F\u0627\u0631\u062F",
    "builder.fragmentPackets": "\u0628\u0633\u062A\u0647\u200C\u0647\u0627",
    "builder.fragmentLength": "\u0637\u0648\u0644 (\u0628\u0627\u06CC\u062A)",
