    "builder.fragmentBad": "\u0628\u0627\u0632\u0647\u200C\u0647\u0627 \u0628\u0627\u06CC\u062F 'tlshello' \u06CC\u0627 'A-B' \u0639\u062F\u062F\u06CC \u0628\u0627\u0634\u0646\u062F \u2014 \u062A\u0627 \u0648\u0642\u062A\u06CC \u0628\u0627\u0632\u0647\u200C\u0627\u06CC \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0627\u0633\u062A\u060C \u0627\u06CC\u0646 \u0642\u0627\u0628\u0644\u06CC\u062A \u0627\u0639\u0645\u0627\u0644 \u0646\u0645\u06CC\u200C\u0634\u0648\u062F.",
