    "qr.importDesc": "\u062E\u0648\u0627\u0646\u062F\u0646 \u0627\u0633\u06A9\u0631\u06CC\u0646\u200C\u0634\u0627\u062A \u06CC\u0627 \u0639\u06A9\u0633 \u06A9\u062F QR",
