    "appopt.hint": "\u0627\u062C\u0631\u0627\u06CC \u062E\u0648\u062F\u06A9\u0627\u0631\u060C \u0645\u06CC\u0627\u0646\u200C\u0628\u0631\u0647\u0627\u06CC \u0633\u0631\u0627\u0633\u0631\u06CC\u060C \u0631\u0641\u062A\u0627\u0631 Tray \u0648 \u067E\u0634\u062A\u06CC\u0628\u0627\u0646\u200C\u06AF\u06CC\u0631\u06CC \u0631\u0627 \u0641\u0631\u0627\u06CC\u0646\u062F \u062F\u0633\u06A9\u062A\u0627\u067E \u0645\u062F\u06CC\u0631\u06CC\u062A \u0645\u06CC\u200C\u06A9\u0646\u062F \u2014 \u0627\u06CC\u0646 \u0635\u0641\u062D\u0647\u200C\u06CC \u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u0648\u0636\u0639\u06CC\u062A \u0648\u0627\u0642\u0639\u06CC \u0622\u0646\u200C\u0647\u0627 \u0631\u0627 \u0646\u0634\u0627\u0646 \u0645\u06CC\u200C\u062F\u0647\u062F\u061B \u067E\u06CC\u0634\u200C\u0646\u0645\u0627\u06CC\u0634 \u0645\u0631\u0648\u0631\u06AF\u0631 \u0647\u0645 \u0622\u0646\u200C\u0647\u0627 \u0631\u0627 \u0634\u0628\u06CC\u0647\u200C\u0633\u0627\u0632\u06CC \u0645\u06CC\u200C\u06A9\u0646\u062F.",
