    "appopt.autostart": "\u0627\u062C\u0631\u0627\u06CC \u062E\u0648\u062F\u06A9\u0627\u0631 \u0628\u0627 \u0648\u06CC\u0646\u062F\u0648\u0632",
    "appopt.autostartHint": "MEMENTO \u0647\u0646\u06AF\u0627\u0645 \u0648\u0631\u0648\u062F \u0628\u0647 \u0648\u06CC\u0646\u062F\u0648\u0632 \u062E\u0648\u062F\u06A9\u0627\u0631 \u0628\u0627\u0632 \u0634\u0648\u062F (\u0645\u062E\u0641\u06CC \u062F\u0631 Tray). \u0628\u0627 exe \u067E\u0631\u062A\u0627\u0628\u0644 \u0647\u0645 \u06A9\u0627\u0631 \u0645\u06CC\u200C\u06A9\u0646\u062F \u2014 \u0627\u06AF\u0631 \u0645\u0633\u06CC\u0631 exe \u0631\u0627 \u062C\u0627\u0628\u0647\u200C\u062C\u0627 \u06CC\u0627 \u062A\u063A\u06CC\u06CC\u0631 \u0646\u0627\u0645 \u062F\u0627\u062F\u06CC\u062F\u060C \u06CC\u06A9\u200C\u0628\u0627\u0631 \u0627\u06CC\u0646 \u06AF\u0632\u06CC\u0646\u0647 \u0631\u0627 \u062E\u0627\u0645\u0648\u0634 \u0648 \u0631\u0648\u0634\u0646 \u06A9\u0646\u06CC\u062F \u062A\u0627 \u0645\u0633\u06CC\u0631 \u062C\u062F\u06CC\u062F \u062B\u0628\u062A \u0634\u0648\u062F",
    "appopt.autostartUnsupported": "\u0627\u062C\u0631\u0627\u06CC \u062E\u0648\u062F\u06A9\u0627\u0631 \u0641\u0642\u0637 \u062F\u0631 \u0627\u067E \u0648\u06CC\u0646\u062F\u0648\u0632\u06CC \u067E\u06A9\u06CC\u062C\u200C\u0634\u062F\u0647 \u06A9\u0627\u0631 \u0645\u06CC\u200C\u06A9\u0646\u062F (exe \u067E\u0631\u062A\u0627\u0628\u0644 \u0647\u0645 \u0634\u0627\u0645\u0644 \u0645\u06CC\u200C\u0634\u0648\u062F) \u2014 \u062F\u0631 \u062D\u0627\u0644\u062A \u062A\u0648\u0633\u0639\u0647/\u0645\u0631\u0648\u0631\u06AF\u0631 \u062F\u0631 \u062F\u0633\u062A\u0631\u0633 \u0646\u06CC\u0633\u062A",
