    "appopt.hotkeyConnHint": "Ctrl+Alt+C \u2014 \u0631\u0648\u0634\u0646/\u062E\u0627\u0645\u0648\u0634 \u06A9\u0631\u062F\u0646 \u0627\u062A\u0635\u0627\u0644 \u0641\u0639\u0644\u06CC \u0627\u0632 \u0647\u0631 \u062C\u0627",
