    "set.closeToTrayHint": "\u062F\u06A9\u0645\u0647\u200C\u06CC \u0636\u0631\u0628\u062F\u0631 MEMENTO \u0631\u0627 \u0628\u0647 Tray \u0645\u06CC\u200C\u0641\u0631\u0633\u062A\u062F \u0648 VPN \u0631\u0648\u0634\u0646 \u0645\u06CC\u200C\u0645\u0627\u0646\u062F \u2014 \u0622\u06CC\u06A9\u0646 Tray \u067E\u0646\u062C\u0631\u0647 \u0631\u0627 \u0628\u0631\u0645\u06CC\u200C\u06AF\u0631\u062F\u0627\u0646\u062F. \u0628\u0631\u0627\u06CC \u062E\u0631\u0648\u062C \u06A9\u0627\u0645\u0644 \u0647\u0646\u06AF\u0627\u0645 \u0628\u0633\u062A\u0646 \u067E\u0646\u062C\u0631\u0647\u060C \u0627\u06CC\u0646 \u06AF\u0632\u06CC\u0646\u0647 \u0631\u0627 \u062E\u0627\u0645\u0648\u0634 \u06A9\u0646\u06CC\u062F",
    "set.killSwitch": "\u06A9\u0644\u06CC\u062F \u0642\u0637\u0639 \u0627\u0636\u0637\u0631\u0627\u0631\u06CC (Kill switch)",
    "set.killSwitchHint": "\u0645\u062D\u0627\u0641\u0638\u062A \u0642\u0637\u0639-\u0628\u0647-\u0647\u0646\u06AF\u0627\u0645: \u0648\u0642\u062A\u06CC \u0631\u0648\u0634\u0646 \u0627\u0633\u062A\u060C \u0647\u0631 \u0628\u0627\u0631 \u06A9\u0647 \u062A\u0648\u0646\u0644 \u0642\u0637\u0639 \u0634\u0648\u062F (\u0642\u0637\u0639 \u062F\u0633\u062A\u06CC \u06CC\u0627 \u06A9\u0631\u0634 \u0647\u0633\u062A\u0647)\u060C \u067E\u0631\u0627\u06A9\u0633\u06CC \u0633\u06CC\u0633\u062A\u0645 \u0628\u0647 \u0622\u062F\u0631\u0633 \u0645\u0631\u062F\u0647\u200C\u06CC \u06F1\u06F2\u06F7.\u06F0.\u06F0.\u06F1:\u06F9 \u0642\u0641\u0644 \u0645\u06CC\u200C\u0634\u0648\u062F \u062A\u0627 \u0628\u0631\u0646\u0627\u0645\u0647\u200C\u0647\u0627\u06CC \u067E\u06CC\u0631\u0648\u06CC\u200C\u06A9\u0646\u0646\u062F\u0647 \u0627\u0632 \u067E\u0631\u0627\u06A9\u0633\u06CC \u0633\u06CC\u0633\u062A\u0645 \u0628\u0647\u200C\u062C\u0627\u06CC \u0646\u0634\u062A IP \u0648\u0627\u0642\u0639\u06CC\u060C \u0627\u06CC\u0646\u062A\u0631\u0646\u062A \u0631\u0627 \u0627\u0632 \u062F\u0633\u062A \u0628\u062F\u0647\u0646\u062F. \u0645\u0633\u0644\u062D\u200C\u06A9\u0631\u062F\u0646 \u062F\u0631 \u062D\u0627\u0644\u062A \u0642\u0637\u0639\u060C \u0628\u0644\u0627\u0641\u0627\u0635\u0644\u0647 \u0645\u0633\u062F\u0648\u062F \u0645\u06CC\u200C\u06A9\u0646\u062F. \u062F\u0631 \u062D\u0627\u0644\u062A VPN Device (TUN) \u0647\u0645\u0627\u0646 \u06A9\u0644\u06CC\u062F \u0646\u06AF\u0647\u200C\u062F\u0627\u0634\u062A\u0646 \u0631\u0627 \u0627\u0646\u062C\u0627\u0645 \u0645\u06CC\u200C\u062F\u0647\u062F: \u0646\u0634\u0633\u062A\u0650 \u0645\u0633\u0644\u062D \u0647\u0646\u06AF\u0627\u0645 \u0645\u0631\u06AF \u0622\u067E\u200C\u0627\u0633\u062A\u0631\u06CC\u0645\u060C \u062A\u0648\u0646\u0644 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0646\u06AF\u0647 \u0645\u06CC\u200C\u062F\u0627\u0631\u062F (\u062F\u0631 \u062D\u0627\u0644 \u0627\u062A\u0635\u0627\u0644 \u0645\u062C\u062F\u062F) \u0648 \u0627\u06AF\u0631 \u0647\u0644\u067E\u0631 \u06AF\u0632\u0627\u0631\u0634\u200C\u062F\u0647\u06CC \u0631\u0627 \u0645\u062A\u0648\u0642\u0641 \u06A9\u0646\u062F\u060C \u067E\u0631\u0627\u06A9\u0633\u06CC \u0633\u06CC\u0633\u062A\u0645 \u0645\u0633\u062F\u0648\u062F \u0645\u06CC\u200C\u0634\u0648\u062F. \u062E\u0631\u0648\u062C \u0627\u0632 \u0628\u0631\u0646\u0627\u0645\u0647 \u0647\u0645\u06CC\u0634\u0647 \u062F\u0633\u062A\u0631\u0633\u06CC \u0645\u0633\u062A\u0642\u06CC\u0645 \u0631\u0627 \u0628\u0631\u0645\u06CC\u200C\u06AF\u0631\u062F\u0627\u0646\u062F. \u062F\u0627\u0645\u0646\u0647\u200C\u06CC \u0635\u0627\u062F\u0642\u0627\u0646\u0647: \u0641\u0642\u0637 \u0628\u0631\u0646\u0627\u0645\u0647\u200C\u0647\u0627\u06CC\u06CC \u0631\u0627 \u0645\u06CC\u200C\u067E\u0648\u0634\u0627\u0646\u062F \u06A9\u0647 \u0627\u0632 \u067E\u0631\u0627\u06A9\u0633\u06CC \u0633\u06CC\u0633\u062A\u0645 \u0648\u06CC\u0646\u062F\u0648\u0632 \u067E\u06CC\u0631\u0648\u06CC \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F \u2014 \u0627\u06CC\u0646 \u0642\u0637\u0639\u0650 \u0633\u0637\u062D \u067E\u0631\u0627\u06A9\u0633\u06CC \u0627\u0633\u062A\u060C \u0646\u0647 \u0641\u0627\u06CC\u0631\u0648\u0627\u0644.",
