    "connection.modeProxyDesc": "\u062A\u0645\u0627\u0645 \u062A\u0631\u0627\u0641\u06CC\u06A9 \u0633\u06CC\u0633\u062A\u0645 \u0627\u0632 \u0637\u0631\u06CC\u0642 \u067E\u0631\u0627\u06A9\u0633\u06CC \u0645\u0633\u06CC\u0631\u06CC\u0627\u0628\u06CC \u0645\u06CC\u200C\u0634\u0648\u062F.",
    "connection.modeTun": "\u062F\u0633\u062A\u06AF\u0627\u0647 VPN (TUN)",
    "connection.modeTunDesc": "\u062A\u0645\u0627\u0645 \u062A\u0631\u0627\u0641\u06CC\u06A9 \u0633\u06CC\u0633\u062A\u0645 \u0627\u0632 \u0637\u0631\u06CC\u0642 \u0622\u062F\u0627\u067E\u062A\u0648\u0631 \u0645\u062C\u0627\u0632\u06CC \u062F\u0627\u062E\u0644 \u062A\u0648\u0646\u0644 \u0639\u0628\u0648\u0631 \u0645\u06CC\u200C\u06A9\u0646\u062F (\u062A\u0623\u06CC\u06CC\u062F UAC \u0644\u0627\u0632\u0645 \u0627\u0633\u062A). \u0628\u0627 \u0647\u0631 \u0646\u0648\u0639 \u06A9\u0627\u0646\u0641\u06CC\u06AF \u0648 \u0647\u0631 \u062F\u0648 \u0647\u0633\u062A\u0647 \u06A9\u0627\u0631 \u0645\u06CC\u200C\u06A9\u0646\u062F.",
    "connection.tunUacAccepted": "\u0645\u062F\u06CC\u0631 \u0633\u06CC\u0633\u062A\u0645 \u062A\u0623\u06CC\u06CC\u062F \u0634\u062F \u2014 \u0622\u062F\u0627\u067E\u062A\u0648\u0631 TUN (\u0628\u0627 \u0646\u0627\u0645 MementoTun) \u062F\u0631 \u062D\u0627\u0644 \u0633\u0627\u062E\u062A\u0647 \u0634\u062F\u0646 \u0627\u0633\u062A\u2026",
    "connection.tunUacFailed": "\u0627\u0631\u062A\u0642\u0627\u06CC \u062F\u0633\u062A\u0631\u0633\u06CC \u0628\u0631\u0627\u06CC \u062F\u0633\u062A\u06AF\u0627\u0647 VPN (TUN) \u0627\u0646\u062C\u0627\u0645 \u0646\u0634\u062F.",
    "tab.updatecenter": "\u0628\u0647\u200C\u0631\u0648\u0632\u0631\u0633\u0627\u0646",
    "tab.googleside": "\u06AF\u0648\u06AF\u0644 \u0633\u0627\u06CC\u062F",
    "tab.liveconn": "\u0644\u0627\u06CC\u0648 \u06A9\u0627\u0646\u06A9\u0634\u0646",
    "updateCenter.title": "\u0628\u0647\u200C\u0631\u0648\u0632\u0631\u0633\u0627\u0646",
    "updateCenter.desc": "\u0628\u0647\u200C\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06CC \u06CC\u06A9\u200C\u06A9\u0644\u06CC\u06A9\u06CC \u0647\u0633\u062A\u0647\u200C\u0647\u0627. \u062F\u0627\u0646\u0644\u0648\u062F \u0627\u0628\u062A\u062F\u0627 \u062A\u0623\u06CC\u06CC\u062F \u0645\u06CC\u200C\u0634\u0648\u062F (\u0628\u0627\u06CC\u0646\u0631\u06CC \u062C\u062F\u06CC\u062F \u0628\u0627\u06CC\u062F \u0627\u062C\u0631\u0627 \u0634\u0648\u062F \u0648 \u0646\u0633\u062E\u0647\u200C\u0627\u0634 \u0631\u0627 \u0627\u0639\u0644\u0627\u0645 \u06A9\u0646\u062F)\u060C \u0628\u0639\u062F \u0628\u0647\u200C\u0635\u0648\u0631\u062A \u0627\u0645\u0646 \u0646\u0635\u0628 \u0645\u06CC\u200C\u0634\u0648\u062F \u2014 \u0646\u0633\u062E\u0647 \u0642\u0628\u0644\u06CC \u0628\u0647\u200C\u0639\u0646\u0648\u0627\u0646 .bak \u0628\u0631\u0627\u06CC \u0628\u0631\u06AF\u0634\u062A \u0646\u06AF\u0647 \u062F\u0627\u0634\u062A\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F. \u0645\u0650\u0645\u0646\u062A\u0648 \u0628\u0627 \u0647\u0631 \u0646\u0633\u062E\u0647\u200C\u0627\u06CC \u0627\u0632 \u0647\u0633\u062A\u0647\u200C\u0647\u0627 \u0633\u0627\u0632\u06AF\u0627\u0631 \u0645\u06CC\u200C\u0645\u0627\u0646\u062F: \u0648\u0642\u062A\u06CC \u0647\u0633\u062A\u0647 \u062C\u062F\u06CC\u062F \u06CC\u06A9 \u0642\u0627\u0628\u0644\u06CC\u062A \u0631\u0627 \u062D\u0630\u0641 \u06A9\u0646\u062F\u060C \u06A9\u0627\u0646\u0641\u06CC\u06AF \u062E\u0648\u062F\u06A9\u0627\u0631 \u062A\u0637\u0628\u06CC\u0642 \u062F\u0627\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F.",
    "updateCenter.phase.checking": "\u0628\u0631\u0631\u0633\u06CC \u0622\u062E\u0631\u06CC\u0646 \u0646\u0633\u062E\u0647\u2026",
