    "updateCenter.err.network": "\u062F\u0633\u062A\u0631\u0633\u06CC \u0628\u0647 GitHub Releases \u0646\u0634\u062F \u2014 \u0627\u06CC\u0646\u062A\u0631\u0646\u062A \u0631\u0627 \u0686\u06A9 \u06A9\u0646 \u0648 \u062F\u0648\u0628\u0627\u0631\u0647 \u0628\u0631\u0631\u0633\u06CC \u0631\u0627 \u0628\u0632\u0646.",
