    "updateCenter.err.extract": "\u0627\u0633\u062A\u062E\u0631\u0627\u062C \u0646\u0627\u0645\u0648\u0641\u0642 \u0628\u0648\u062F.",
    "updateCenter.err.noBinary": "\u0641\u0627\u06CC\u0644 \u0627\u062C\u0631\u0627\u06CC\u06CC \u062F\u0627\u062E\u0644 \u0641\u0627\u06CC\u0644 \u062F\u0627\u0646\u0644\u0648\u062F\u0634\u062F\u0647 \u067E\u06CC\u062F\u0627 \u0646\u0634\u062F.",
    "updateCenter.err.verifyRun": "\u0641\u0627\u06CC\u0644 \u0627\u062C\u0631\u0627\u06CC\u06CC \u062F\u0627\u0646\u0644\u0648\u062F\u0634\u062F\u0647 \u0631\u0648\u06CC \u0627\u06CC\u0646 \u0633\u06CC\u0633\u062A\u0645 \u0627\u062C\u0631\u0627 \u0646\u0634\u062F.",
    "updateCenter.err.verifyVersion": "\u0646\u0633\u062E\u0647 \u0641\u0627\u06CC\u0644 \u0627\u062C\u0631\u0627\u06CC\u06CC \u062F\u0627\u0646\u0644\u0648\u062F\u0634\u062F\u0647 \u0628\u0627 \u0646\u0633\u062E\u0647 \u0645\u0648\u0631\u062F \u0627\u0646\u062A\u0638\u0627\u0631 \u0641\u0631\u0642 \u062F\u0627\u0631\u062F.",
    "updateCenter.err.blockedRunning": "\u0647\u0633\u062A\u0647 \u062F\u0631 \u062D\u0627\u0644 \u0627\u062C\u0631\u0627\u0633\u062A \u2014 \u0627\u0648\u0644 \u0642\u0637\u0639 \u06A9\u0646\u060C \u0628\u0639\u062F \u062F\u0648\u0628\u0627\u0631\u0647 \u0646\u0635\u0628 \u0631\u0627 \u0628\u0632\u0646.",
    "updateCenter.err.apply": "\u0646\u0635\u0628 \u0646\u0627\u0645\u0648\u0641\u0642 \u0628\u0648\u062F \u2014 \u0646\u0633\u062E\u0647 \u0642\u0628\u0644\u06CC \u0628\u0631\u06AF\u0631\u062F\u0627\u0646\u062F\u0647 \u0634\u062F.",
    "updateCenter.err.noAsset": "\u0641\u0627\u06CC\u0644 \u0642\u0627\u0628\u0644 \u062F\u0627\u0646\u0644\u0648\u062F\u06CC \u0628\u0631\u0627\u06CC \u0627\u06CC\u0646 \u067E\u0644\u062A\u0641\u0631\u0645 \u0646\u06CC\u0633\u062A.",
    "liveconn.title": "\u0644\u0627\u06CC\u0648 \u06A9\u0627\u0646\u06A9\u0634\u0646",
    "liveconn.desc": "\u0647\u0645\u0647 \u0628\u0631\u0646\u0627\u0645\u0647\u200C\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u0647\u0645\u06CC\u0646 \u0627\u0644\u0627\u0646 \u0627\u0632 \u0627\u06CC\u0646\u062A\u0631\u0646\u062A \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F \u2014 \u0633\u0648\u06A9\u062A\u200C\u0647\u0627\u06CC \u0648\u0627\u0642\u0639\u06CC \u0633\u06CC\u0633\u062A\u0645\u200C\u0639\u0627\u0645\u0644\u060C \u0628\u0647\u200C\u0635\u0648\u0631\u062A \u0632\u0646\u062F\u0647. \u0631\u0648\u06CC \u0647\u0631 \u0628\u0631\u0646\u0627\u0645\u0647 \u0628\u0632\u0646 \u062A\u0627 \u0645\u0642\u0635\u062F\u0647\u0627\u06CC \u0627\u06CC\u0646\u062A\u0631\u0646\u062A\u06CC\u200C\u0627\u0634 \u0631\u0627 \u0628\u0628\u06CC\u0646\u06CC.",
    "googleside.title": "\u06AF\u0648\u06AF\u0644 \u0633\u0627\u06CC\u062F \u2014 MHRV",
    "googleside.desc": "MasterHttpRelayVPN \u062F\u0627\u062E\u0644 \u062E\u0648\u062F \u0645\u0650\u0645\u0646\u062A\u0648: \u062D\u0633\u0627\u0628 \u06AF\u0648\u06AF\u0644 \u062E\u0648\u062F\u062A \u0645\u06CC\u200C\u0634\u0648\u062F \u06CC\u06A9 \u0631\u0644\u0647 \u0631\u0627\u06CC\u06AF\u0627\u0646 \u06A9\u0647 \u0633\u0627\u0646\u0633\u0648\u0631 (DPI) \u0631\u0627 \u062F\u0648\u0631 \u0645\u06CC\u200C\u0632\u0646\u062F (\u0641\u0642\u0637 google.com \u062F\u06CC\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F). \u0647\u0645\u0647\u200C\u0686\u06CC\u0632 \u062F\u0627\u062E\u0644 \u0628\u0631\u0646\u0627\u0645\u0647 \u0627\u0633\u062A \u2014 \u0627\u0633\u06A9\u0631\u06CC\u067E\u062A Code.gs\u060C \u062F\u0627\u0645\u0646\u0647\u200C\u0647\u0627\u06CC \u06AF\u0648\u06AF\u0644\u060C \u0627\u0633\u06A9\u0646\u0631\u0647\u0627\u06CC IP/SNI \u2014 \u0646\u0647 \u0686\u06CC\u0632\u06CC \u0628\u0631\u0627\u06CC \u062F\u0627\u0646\u0644\u0648\u062F \u0646\u0647 \u0686\u06CC\u0632\u06CC \u0628\u0631\u0627\u06CC \u0646\u0635\u0628.",
    "connection.port": "\u067E\u0648\u0631\u062A",
    "connection.tauriMode": "\u062D\u0627\u0644\u062A \u062F\u0633\u06A9\u062A\u0627\u067E \u2014 xray-core \u0622\u0645\u0627\u062F\u0647",
    "connection.tauriDesc": "\u0645\u0650\u0645\u0646\u062A\u0648 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u0627\u067E\u0644\u06CC\u06A9\u06CC\u0634\u0646 \u0627\u062C\u0631\u0627 \u0634\u062F\u0647 \u0648 xray-core \u0631\u0627 \u062E\u0648\u062F\u06A9\u0627\u0631 \u0645\u062F\u06CC\u0631\u06CC\u062A \u0645\u06CC\u200C\u06A9\u0646\u062F.",
    "connection.browserMode": "\u062D\u0627\u0644\u062A \u0645\u0631\u0648\u0631\u06AF\u0631 \u2014 \u0646\u06CC\u0627\u0632 \u0628\u0647 \u062A\u0646\u0638\u06CC\u0645 \u062F\u0633\u062A\u06CC",
    "connection.browserDesc": "\u062F\u0631 \u062D\u0627\u0644\u062A \u0645\u0631\u0648\u0631\u06AF\u0631\u060C \u0645\u0650\u0645\u0646\u062A\u0648 JSON \u06A9\u0627\u0646\u0641\u06CC\u06AF xray-core \u0631\u0627 \u0628\u0631\u0627\u06CC \u0634\u0645\u0627 \u062A\u0648\u0644\u06CC\u062F \u0645\u06CC\u200C\u06A9\u0646\u062F. \u0622\u0646 \u0631\u0627 \u06A9\u067E\u06CC \u06A9\u0646\u06CC\u062F \u0648 xray \u0631\u0627 \u062F\u0633\u062A\u06CC \u0627\u062C\u0631\u0627 \u06A9\u0646\u06CC\u062F\u060C \u06CC\u0627 \u0645\u0650\u0645\u0646\u062A\u0648 \u0631\u0627 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u0627\u067E \u062F\u0633\u06A9\u062A\u0627\u067E \u0628\u06CC\u0644\u062F \u06A9\u0646\u06CC\u062F.",
    "connection.configPreview": "\u06A9\u0627\u0646\u0641\u06CC\u06AF JSON xray-core",
    "connection.selectToPreview": "\u06CC\u06A9 \u06A9\u0627\u0646\u0641\u06CC\u06AF \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F \u062A\u0627 JSON \u0622\u0646 \u0631\u0627 \u0628\u0628\u06CC\u0646\u06CC\u062F.",
    "connection.quickStart": "\u0631\u0627\u0647\u0646\u0645\u0627\u06CC \u0634\u0631\u0648\u0639 \u0633\u0631\u06CC\u0639",
    "connection.step1": "<strong>xray-core \u0631\u0627 \u062F\u0627\u0646\u0644\u0648\u062F \u06A9\u0646\u06CC\u062F</strong> \u0627\u0632 GitHub \u0631\u0633\u0645\u06CC.",
    "connection.step2": "<strong>xray.exe \u0631\u0627 \u0627\u0633\u062A\u062E\u0631\u0627\u062C \u06A9\u0646\u06CC\u062F</strong> \u06A9\u0646\u0627\u0631 \u0641\u0627\u06CC\u0644 MEMENTO.exe.",
    "connection.step3": "<strong>\u06CC\u06A9 \u06A9\u0627\u0646\u0641\u06CC\u06AF \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F</strong> \u0627\u0632 \u0644\u06CC\u0633\u062A \u0628\u0627\u0644\u0627.",
    "connection.step4": "<strong>\u062F\u06A9\u0645\u0647 \u0627\u062A\u0635\u0627\u0644 \u0631\u0627 \u0628\u0632\u0646\u06CC\u062F</strong> \u2014 \u0645\u0650\u0645\u0646\u062A\u0648 \u0647\u0645\u0647 \u0686\u06CC\u0632 \u0631\u0627 \u062E\u0648\u062F\u06A9\u0627\u0631 \u0627\u0646\u062C\u0627\u0645 \u0645\u06CC\u200C\u062F\u0647\u062F.",
    "connection.stoppedUnexpectedly": "{core} \u0628\u0647\u200C\u0637\u0648\u0631 \u063A\u06CC\u0631\u0645\u0646\u062A\u0638\u0631\u0647 \u0645\u062A\u0648\u0642\u0641 \u0634\u062F \u2014 \u0627\u062A\u0635\u0627\u0644 \u0642\u0637\u0639 \u0634\u062F.",
