    "connections.none": "\u0627\u06CC\u0646 \u0647\u0633\u062A\u0647 \u0647\u06CC\u0686 \u0631\u0627\u0628\u0637 \u0622\u0645\u0627\u0631 \u0627\u062A\u0635\u0627\u0644\u06CC \u0627\u0631\u0627\u0626\u0647 \u0646\u0645\u06CC\u200C\u062F\u0647\u062F.",
