    "topo.chain": "\u067E\u0631\u0648\u06A9\u0633\u06CC \u0632\u0646\u062C\u06CC\u0631\u0647\u200C\u0627\u06CC (\u0647\u0627\u067E \u0627\u0648\u0644)",
    "topo.chainHint": "\u0627\u062A\u0635\u0627\u0644 \u062A\u0648\u0646\u0644 \u0627\u0648\u0644 \u0627\u0632 \u06CC\u06A9 \u06A9\u0627\u0646\u0641\u06CC\u06AF \u062F\u06CC\u06AF\u0631 \u0631\u062F \u0645\u06CC\u200C\u0634\u0648\u062F \u2014 \u0633\u0631\u0648\u0631 \u0622\u06CC\u200C\u067E\u06CC\u0650 \u0647\u0627\u067E \u0631\u0627 \u0645\u06CC\u200C\u0628\u06CC\u0646\u062F\u060C \u0646\u0647 \u0622\u06CC\u200C\u067E\u06CC \u0634\u0645\u0627 \u0631\u0627.",
    "topo.chainHop": "\u06A9\u0627\u0646\u0641\u06CC\u06AF \u0647\u0627\u067E (\u0627\u0648\u0644\u06CC\u0646 \u0647\u0627\u067E\u06CC \u06A9\u0647 \u062A\u0648\u0646\u0644 \u0627\u0632 \u0622\u0646 \u0631\u062F \u0645\u06CC\u200C\u0634\u0648\u062F)",
