    "topo.chainNote": "\u0648\u0642\u062A\u06CC \u0632\u0646\u062C\u06CC\u0631\u0647 \u0641\u0639\u0627\u0644 \u0627\u0633\u062A\u060C TLS Fragment (\u062A\u0646\u0638\u06CC\u0645\u0627\u062A) \u0628\u0647 \u0647\u0627\u067E \u0645\u0646\u062A\u0642\u0644 \u0645\u06CC\u200C\u0634\u0648\u062F \u2014 ClientHello\u0650 \u0647\u0645\u0627\u0646 \u0647\u0627\u067E \u062A\u06A9\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F \u0648 \u0641\u0642\u0637 \u0648\u0642\u062A\u06CC \u0647\u0627\u067E TLS/Reality \u062F\u0627\u0631\u062F \u0627\u0639\u0645\u0627\u0644 \u0645\u06CC\u200C\u0634\u0648\u062F.",
    "topo.chainCoreNote": "\u0647\u0627\u067E \u0628\u0627\u06CC\u062F \u0631\u0648\u06CC \u0647\u0645\u0627\u0646 \u0647\u0633\u062A\u0647\u200C\u06CC \u06A9\u0627\u0646\u0641\u06CC\u06AF \u0645\u062A\u0635\u0644 \u0628\u0627\u0634\u062F (vmess/vless/trojan/ss/socks = Xray\u060C hysteria2/tuic = sing-box). \u0632\u0646\u062C\u06CC\u0631\u0647\u200C\u06A9\u0631\u062F\u0646 \u06A9\u0627\u0646\u0641\u06CC\u06AF \u0628\u0647 \u062E\u0648\u062F\u0634 \u0628\u0627 \u0627\u0637\u0644\u0627\u0639\u200C\u0631\u0633\u0627\u0646\u06CC \u0631\u062F \u0645\u06CC\u200C\u0634\u0648\u062F.",
    "topo.balancer": "\u0628\u0627\u0644\u0627\u0646\u0633\u0631 (\u062A\u0648\u0632\u06CC\u0639 \u0628\u0627\u0631 \u0628\u06CC\u0646 \u06A9\u0627\u0646\u0641\u06CC\u06AF\u200C\u0647\u0627)",
    "topo.balancerHint": "\u06A9\u0627\u0646\u0641\u06CC\u06AF \u0645\u062A\u0635\u0644 \u0647\u0645\u06CC\u0634\u0647 \u0639\u0636\u0648 \u0627\u0648\u0644 \u0627\u0633\u062A\u062E\u0631 \u0627\u0633\u062A\u061B \u0647\u0631 \u0639\u0636\u0648 \u0627\u0636\u0627\u0641\u0647 \u0628\u062E\u0634\u06CC \u0627\u0632 \u062A\u0631\u0627\u0641\u06CC\u06A9 \u0631\u0627 \u0645\u06CC\u200C\u0628\u0631\u062F. \u0633\u0631\u0639\u062A \u0648 \u062D\u062C\u0645 \u062C\u0645\u0639\u0650 \u0647\u0645\u0647\u200C\u06CC \u0627\u0639\u0636\u0627\u0633\u062A. \u0646\u06A9\u062A\u0647\u200C\u06CC \u0647\u0633\u062A\u0647\u200C\u06CC Xray: \u0648\u0642\u062A\u06CC \u0628\u0627\u0644\u0627\u0646\u0633\u0631 \u0641\u0639\u0627\u0644 \u0627\u0633\u062A\u060C \u062E\u0648\u062F\u0650 \u0647\u0633\u062A\u0647 \u0628\u0627\u06CC\u062A\u200C\u0647\u0627\u06CC \u0622\u067E\u0644\u0648\u062F\u0650 \u0627\u0639\u0636\u0627\u06CC vless \u0631\u0627 \u0646\u0645\u06CC\u200C\u0634\u0645\u0627\u0631\u062F (\u062F\u0627\u0646\u0644\u0648\u062F \u0639\u0627\u062F\u06CC \u0634\u0645\u0631\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F).",
    "topo.strategy": "\u0627\u0633\u062A\u0631\u0627\u062A\u0698\u06CC",
