    "aether.hintMasque": "MASQUE \u0631\u0648\u06CC QUIC/HTTP-3 \u2014 \u062A\u0646\u0647\u0627 \u067E\u0631\u0648\u062A\u06A9\u0644\u06CC \u06A9\u0647 \u0628\u0627 \u0627\u06CC\u0646 \u0628\u06CC\u0644\u062F \u0628\u0647\u200C\u0635\u0648\u0631\u062A \u0633\u0631\u062A\u0627\u0633\u0631\u06CC \u0632\u0646\u062F\u0647 \u062A\u0633\u062A \u0634\u062F\u0647\u061B \u067E\u06CC\u0634\u200C\u0641\u0631\u0636 \u067E\u06CC\u0634\u0646\u0647\u0627\u062F\u06CC.",
