    "aether.systemProxyHint": "\u0628\u0647\u200C\u0635\u0648\u0631\u062A \u067E\u06CC\u0634\u200C\u0641\u0631\u0636 \u062E\u0627\u0645\u0648\u0634. \u0628\u0627 \u0634\u0646\u0648\u0646\u062F\u0647\u200C\u06CC SOCKS5 \u062A\u0646\u0647\u0627\u060C \u0628\u0631\u0646\u0627\u0645\u0647\u200C\u0647\u0627\u06CC system-proxy \u0628\u0647 \u067E\u0634\u062A\u06CC\u0628\u0627\u0646\u06CC SOCKS5 \u0646\u06CC\u0627\u0632 \u062F\u0627\u0631\u0646\u062F \u2014 \u0628\u0631\u0627\u06CC \u067E\u0631\u0627\u06A9\u0633\u06CC \u06A9\u0627\u0645\u0644 \u0633\u06CC\u0633\u062A\u0645\u060C \u0634\u0646\u0648\u0646\u062F\u0647\u200C\u06CC HTTP \u0631\u0627 \u062F\u0631 \u067E\u0627\u06CC\u06CC\u0646 \u0641\u0639\u0627\u0644 \u06A9\u0646\u06CC\u062F.",
