    "aether.modeSocksDesc": "\u0634\u0646\u0648\u0646\u062F\u0647\u200C\u06CC \u0645\u062D\u0644\u06CC SOCKS5 \u2014 \u0628\u0631\u0646\u0627\u0645\u0647\u200C\u0647\u0627 \u0627\u0632 \u0637\u0631\u06CC\u0642 \u06A9\u0644\u06CC\u062F \u067E\u0631\u0627\u06A9\u0633\u06CC \u0633\u06CC\u0633\u062A\u0645 \u062F\u0631 \u067E\u0627\u06CC\u06CC\u0646 \u0628\u0647 \u062A\u0648\u0646\u0644 \u0645\u06CC\u200C\u0631\u0633\u0646\u062F.",
