    "aether.vpnDeviceCard": "\u0646\u0634\u0633\u062A \u062F\u0633\u062A\u06AF\u0627\u0647 VPN",
    "aether.vpnDeviceHint": "\u062A\u0645\u0627\u0645 \u062A\u0631\u0627\u0641\u06CC\u06A9 \u0633\u06CC\u0633\u062A\u0645 \u0631\u0627 \u0627\u0632 \u0622\u062F\u0627\u067E\u062A\u0648\u0631 TUN \u0628\u0647 \u0634\u0646\u0648\u0646\u062F\u0647\u200C\u06CC SOCKS \u0647\u0645\u06CC\u0646 \u0627\u062A\u0635\u0627\u0644 \u0645\u06CC\u200C\u0641\u0631\u0633\u062A\u062F. \u0648\u06CC\u0646\u062F\u0648\u0632 \u062A\u0623\u06CC\u06CC\u062F \u0645\u062F\u06CC\u0631 (UAC) \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u062F\u061B \u062A\u0646\u0638\u06CC\u0645 Kill Switch \u062A\u0639\u06CC\u06CC\u0646 \u0645\u06CC\u200C\u06A9\u0646\u062F \u0627\u06AF\u0631 \u0628\u0627\u0644\u0627\u062F\u0633\u062A \u0642\u0637\u0639 \u0634\u0648\u062F \u0686\u0647 \u0634\u0648\u062F: \u0645\u0633\u0644\u062D\u060C \u0645\u0633\u062F\u0648\u062F \u0645\u06CC\u200C\u0645\u0627\u0646\u062F\u061B \u063A\u06CC\u0631\u0645\u0633\u0644\u062D\u060C \u062F\u0633\u062A\u0631\u0633\u06CC \u0645\u0633\u062A\u0642\u06CC\u0645 \u0628\u0631\u0645\u06CC\u200C\u06AF\u0631\u062F\u062F. \u062E\u0631\u0648\u062C \u0627\u0632 \u0628\u0631\u0646\u0627\u0645\u0647 \u0647\u0645\u06CC\u0634\u0647 \u0634\u0628\u06A9\u0647 \u0631\u0627 \u0628\u0631\u0645\u06CC\u200C\u06AF\u0631\u062F\u0627\u0646\u062F.",
    "aether.vpnDeviceProxyNote": "\u062F\u0631 \u062D\u0627\u0644\u062A \u062F\u0633\u062A\u06AF\u0627\u0647 VPN \u06A9\u0644\u06CC\u062F \u067E\u0631\u0627\u06A9\u0633\u06CC \u0633\u06CC\u0633\u062A\u0645 \u0646\u06CC\u0633\u062A \u2014 \u0622\u062F\u0627\u067E\u062A\u0648\u0631 TUN \u062E\u0648\u062F\u0634 \u0647\u0645\u0647\u200C\u06CC \u062A\u0631\u0627\u0641\u06CC\u06A9 \u0633\u06CC\u0633\u062A\u0645 \u0631\u0627 \u0645\u0633\u06CC\u0631\u06CC\u0627\u0628\u06CC \u0645\u06CC\u200C\u06A9\u0646\u062F \u0648 \u062A\u063A\u06CC\u06CC\u0631\u0627\u062A \u067E\u0631\u0627\u06A9\u0633\u06CC \u0633\u06CC\u0633\u062A\u0645 \u062A\u0627 \u067E\u0627\u06CC\u0627\u0646 \u0646\u0634\u0633\u062A \u0645\u0633\u062F\u0648\u062F \u0627\u0633\u062A.",
