    "aether.attribution": "Aether \u067E\u0631\u0648\u0698\u0647\u200C\u0627\u06CC \u0645\u0633\u062A\u0642\u0644 \u0627\u0632 CluvexStudio \u0627\u0633\u062A\u061B \u0645\u0650\u0645\u0646\u062A\u0648 \u06CC\u06A9 wrapper \u063A\u06CC\u0631\u0631\u0633\u0645\u06CC \u0627\u0633\u062A \u0648 \u0647\u06CC\u0686 \u0648\u0627\u0628\u0633\u062A\u06AF\u06CC \u06CC\u0627 \u062A\u0623\u06CC\u06CC\u062F\u06CC \u0627\u0632 \u0646\u0648\u06CC\u0633\u0646\u062F\u06AF\u0627\u0646 \u0622\u0646 \u0646\u062F\u0627\u0631\u062F.",
    "aether.updateTitle": "\u0628\u0647\u200C\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06CC \u0647\u0633\u062A\u0647\u200C\u06CC Aether",
    "aether.updateHint": "\u067E\u06CC\u0646-\u0628\u0647-\u0627\u0632\u0627\u06CC-\u0646\u0633\u062E\u0647: \u0641\u0642\u0637 \u0646\u0633\u062E\u0647\u200C\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u062F\u0631 \u062C\u062F\u0648\u0644 \u067E\u06CC\u0646 \u0647\u0645\u06CC\u0646 build \u062B\u0628\u062A \u0634\u062F\u0647\u200C\u0627\u0646\u062F \u0642\u0627\u0628\u0644 \u0646\u0635\u0628\u200C\u0627\u0646\u062F \u0648 \u0647\u0631 \u062F\u0627\u0646\u0644\u0648\u062F \u067E\u06CC\u0634 \u0627\u0632 \u0646\u0648\u0634\u062A\u0646\u0650 \u0647\u0631 \u0641\u0627\u06CC\u0644\u06CC \u0628\u0627 sha256 \u0647\u0645\u0627\u0646 \u062C\u062F\u0648\u0644 \u062A\u0623\u06CC\u06CC\u062F \u0645\u06CC\u200C\u0634\u0648\u062F. \u0628\u0631\u0646\u0627\u0645\u0647 \u0647\u06CC\u0686\u200C\u0648\u0642\u062A \u062E\u0648\u062F\u0634 \u0628\u0631\u0631\u0633\u06CC \u0646\u0645\u06CC\u200C\u06A9\u0646\u062F \u2014 \u0628\u0631\u0631\u0633\u06CC \u0641\u0642\u0637 \u0628\u0627 \u06A9\u0644\u06CC\u06A9 \u0634\u0645\u0627 \u0627\u0646\u062C\u0627\u0645 \u0645\u06CC\u200C\u0634\u0648\u062F \u0648 \u0628\u062F\u0648\u0646 \u0622\u0646 \u067E\u06CC\u0646 \u0628\u0627\u0646\u062F\u0644\u200C\u0634\u062F\u0647 \u0641\u0639\u0627\u0644 \u0645\u06CC\u200C\u0645\u0627\u0646\u062F. \u0645\u0633\u06CC\u0631 \u0628\u0631\u0631\u0633\u06CC/\u062F\u0627\u0646\u0644\u0648\u062F \u0647\u0631\u06AF\u0632 \u0647\u06CC\u0686 \u062A\u0646\u0638\u06CC\u0645 \u0633\u06CC\u0633\u062A\u0645\u06CC \u0631\u0627 \u0644\u0645\u0633 \u0646\u0645\u06CC\u200C\u06A9\u0646\u062F.",
