    "set.appUpdateTitle": "\u0628\u0647\u200C\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06CC MEMENTO",
    "set.appUpdateHint": "\u06CC\u06A9 \u06A9\u0645\u06A9\u200C\u06CC\u0627\u0631 \u0635\u0627\u062F\u0642\u0627\u0646\u0647\u060C \u0646\u0647 \u06CC\u06A9 \u0622\u067E\u062F\u06CC\u062A\u200C\u06A9\u0646\u0646\u062F\u0647: \u0627\u06CC\u0646 \u0628\u0631\u0646\u0627\u0645\u0647 \u0647\u06CC\u0686\u200C\u0648\u0642\u062A \u0628\u0631\u0627\u06CC \u062E\u0648\u062F\u0634 \u0634\u0628\u06A9\u0647 \u0631\u0627 \u0628\u0631\u0631\u0633\u06CC \u0646\u0645\u06CC\u200C\u06A9\u0646\u062F\u060C \u0686\u06CC\u0632\u06CC \u062F\u0627\u0646\u0644\u0648\u062F \u0646\u0645\u06CC\u200C\u06A9\u0646\u062F \u0648 \u0647\u0631\u06AF\u0632 \u0641\u0627\u06CC\u0644 \u0627\u062C\u0631\u0627\u06CC\u06CC \u062E\u0648\u062F\u0634 \u0631\u0627 \u0639\u0648\u0636 \u0646\u0645\u06CC\u200C\u06A9\u0646\u062F. \u06A9\u0646\u062A\u0631\u0644\u0650 \u0647\u0631 \u0642\u062F\u0645 \u062F\u0633\u062A \u0634\u0645\u0627\u0633\u062A.",
    "set.appUpdateThisBuild": "\u0627\u06CC\u0646 build",
