    "set.appUpdateSteps": "\u0628\u0647\u200C\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06CC \u062F\u0633\u062A\u06CC (\u067E\u0631\u062A\u0627\u0628\u0644): \u06F1. MEMENTO \u0631\u0627 \u06A9\u0627\u0645\u0644 \u0628\u0628\u0646\u062F\u06CC\u062F. \u06F2. build \u067E\u0631\u062A\u0627\u0628\u0644 \u062C\u062F\u06CC\u062F \u0631\u0627 \u0627\u0632 \u0635\u0641\u062D\u0647\u200C\u06CC \u0627\u0646\u062A\u0634\u0627\u0631\u0647\u0627 \u0628\u06AF\u06CC\u0631\u06CC\u062F. \u06F3. \u067E\u0648\u0634\u0647/exe \u0642\u062F\u06CC\u0645\u06CC \u0631\u0627 \u0628\u0627 \u062C\u062F\u06CC\u062F \u062C\u0627\u06CC\u06AF\u0632\u06CC\u0646 \u06A9\u0646\u06CC\u062F. \u06F4. MEMENTO \u0631\u0627 \u0627\u062C\u0631\u0627 \u06A9\u0646\u06CC\u062F \u2014 \u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u0648 \u0647\u0633\u062A\u0647\u200C\u0647\u0627 \u062D\u0641\u0638 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F.",
