    "desc.import": "\u0623\u062F\u062E\u0644 \u0625\u0639\u062F\u0627\u062F\u0627\u062A V2Ray \u0625\u0644\u0649 MEMENTO \u0645\u0646 \u0646\u0635 \u0623\u0648 \u0627\u0644\u062D\u0627\u0641\u0638\u0629 \u0623\u0648 \u0645\u0644\u0641 .txt \u0623\u0648 \u0631\u0627\u0628\u0637 \u0627\u0634\u062A\u0631\u0627\u0643. \u064A\u062F\u0639\u0645 \u062C\u0645\u064A\u0639 \u0627\u0644\u0628\u0631\u0648\u062A\u0648\u0643\u0648\u0644\u0627\u062A \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629 \u0648\u0642\u0648\u0627\u0626\u0645 base64.",
    "desc.configs": "\u062A\u0635\u0641\u062D \u0643\u0644 \u0625\u0639\u062F\u0627\u062F \u0645\u0633\u062A\u0648\u0631\u062F \u0641\u064A \u062C\u062F\u0648\u0644 \u0642\u0648\u064A. \u0627\u0628\u062D\u062B \u0648\u0635\u0641\u0650\u0651 \u062D\u0633\u0628 \u0627\u0644\u0628\u0631\u0648\u062A\u0648\u0643\u0648\u0644 \u0648\u0631\u062A\u0651\u0628 \u0648\u062D\u062F\u062F \u0628\u0634\u0643\u0644 \u062C\u0645\u0627\u0639\u064A \u0648\u0648\u0633\u0651\u0639 \u0623\u064A \u0635\u0641 \u0644\u0641\u062D\u0635 \u062A\u0641\u0627\u0635\u064A\u0644\u0647 \u0627\u0644\u0643\u0627\u0645\u0644\u0629.",
    "desc.editor": "\u0623\u0639\u062F \u0643\u062A\u0627\u0628\u0629 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0628\u0634\u0643\u0644 \u062C\u0645\u0627\u0639\u064A. \u0627\u0633\u062A\u062E\u062F\u0645 IP Range \u0644\u0646\u0633\u062E \u0625\u0639\u062F\u0627\u062F \u0639\u0628\u0631 \u0646\u0637\u0627\u0642 IP \u0643\u0627\u0645\u0644\u060C \u0623\u0648 Spoof \u0644\u062A\u0639\u064A\u064A\u0646 IP \u0648\u0645\u0646\u0641\u0630 \u0645\u062E\u0635\u0635 \u0644\u062C\u0645\u064A\u0639 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u062F\u0641\u0639\u0629 \u0648\u0627\u062D\u062F\u0629.",
    "desc.pinger": "\u0642\u0650\u0633 \u0632\u0645\u0646 \u0627\u0633\u062A\u062C\u0627\u0628\u0629 \u062E\u0627\u062F\u0645 \u0643\u0644 \u0625\u0639\u062F\u0627\u062F. \u064A\u0639\u0631\u0636 MEMENTO \u0627\u0644\u0627\u0633\u0645 \u0648\u0627\u0644\u0628\u0631\u0648\u062A\u0648\u0643\u0648\u0644 \u0648\u0639\u0646\u0648\u0627\u0646 IP \u0648\u0627\u0644\u0645\u0646\u0641\u0630 \u0648\u0627\u0644\u0646\u0642\u0644 \u0648\u0642\u064A\u0645\u0629 Ping \u0645\u0644\u0648\u0651\u0646\u0629 \u0644\u0643\u0644 \u0625\u062F\u062E\u0627\u0644.",
    "desc.scanner": "\u0627\u0644\u0635\u0642 \u0623\u0648 \u062D\u0645\u0651\u0644 \u0642\u0627\u0626\u0645\u0629 \u0628\u0639\u0646\u0627\u0648\u064A\u0646 IP \u0648\u0633\u064A\u0642\u0648\u0645 MEMENTO \u0628\u0627\u062E\u062A\u0628\u0627\u0631 Ping \u0644\u0643\u0644 \u0645\u0646\u0647\u0627\u060C \u0645\u0639 \u0639\u0631\u0636 \u0627\u0644\u062A\u0642\u062F\u0645 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0648\u062A\u0642\u0631\u064A\u0631 \u0632\u0645\u0646 \u0627\u0633\u062A\u062C\u0627\u0628\u0629 \u0645\u0644\u0648\u0651\u0646 \u0648\u0648\u0627\u0636\u062D.",
    "desc.export": "\u062D\u0648\u0651\u0644 \u0625\u0639\u062F\u0627\u062F\u0627\u062A\u0643 \u0625\u0644\u0649 \u0623\u064A \u0635\u064A\u063A\u0629 \u062A\u062D\u062A\u0627\u062C\u0647\u0627 \u2014 \u0631\u0648\u0627\u0628\u0637 \u062E\u0627\u0645 \u0623\u0648 \u0627\u0634\u062A\u0631\u0627\u0643 base64 \u0623\u0648 JSON \u0623\u0648 Clash \u0623\u0648 Surge \u0623\u0648 Sing-Box \u2014 \u062B\u0645 \u0627\u0646\u0633\u062E \u0623\u0648 \u0646\u0632\u0651\u0644 \u0628\u0646\u0642\u0631\u0629 \u0648\u0627\u062D\u062F\u0629.",
    "desc.connection": "\u0627\u0644\u0627\u062A\u0635\u0627\u0644 \u0628\u062E\u0627\u062F\u0645 V2Ray \u0648\u062A\u0645\u0631\u064A\u0631 \u062D\u0631\u0643\u0629 \u0646\u0638\u0627\u0645\u0643 \u0639\u0628\u0631\u0647. \u0627\u062E\u062A\u0631 \u0625\u0639\u062F\u0627\u062F\u064B\u0627\u060C \u0648\u062D\u062F\u062F \u0648\u0636\u0639 \u0627\u0644\u0627\u062A\u0635\u0627\u0644 (\u0645\u0628\u0627\u0634\u0631 \u0623\u0648 \u0648\u0643\u064A\u0644 \u0627\u0644\u0646\u0638\u0627\u0645)\u060C \u0648\u0627\u062A\u0635\u0644 \u0628\u0646\u0642\u0631\u0629 \u0648\u0627\u062D\u062F\u0629. \u064A\u062F\u064A\u0631 MEMENTO \u0646\u0648\u0627\u0629 xray-core \u0641\u064A \u0627\u0644\u062E\u0644\u0641\u064A\u0629.",
