    "builder.allowLanWarning": "\u062A\u062D\u0630\u064A\u0631 \u0623\u0645\u0646\u064A: \u0645\u0639 0.0.0.0 \u064A\u0635\u0628\u062D \u0627\u0644\u0628\u0631\u0648\u0643\u0633\u064A \u0627\u0644\u0645\u062D\u0644\u064A SOCKS/HTTP \u0645\u062A\u0627\u062D\u0627\u064B \u062F\u0648\u0646 \u0645\u0635\u0627\u062F\u0642\u0629 \u0644\u0643\u0644 \u0627\u0644\u0623\u062C\u0647\u0632\u0629 \u0641\u064A \u0634\u0628\u0643\u062A\u0643 \u2014 \u0623\u064A \u0634\u062E\u0635 \u0641\u064A \u0646\u0641\u0633 \u0627\u0644\u0634\u0628\u0643\u0629 \u0627\u0644\u0645\u062D\u0644\u064A\u0629 \u064A\u0645\u0643\u0646\u0647 \u062A\u0645\u0631\u064A\u0631 \u062A\u0631\u0627\u0641\u064A\u0643\u0647 \u0639\u0628\u0631 \u062C\u0647\u0627\u0632\u0643 \u0648\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0639\u0646\u0648\u0627\u0646 IP \u0627\u0644\u062E\u0631\u0648\u062C\u064A \u0627\u0644\u062E\u0627\u0635 \u0628\u0643. \u0641\u0639\u0651\u0644\u0647 \u0641\u064A \u0627\u0644\u0634\u0628\u0643\u0627\u062A \u0627\u0644\u0645\u0648\u062B\u0648\u0642\u0629 \u0641\u0642\u0637.",
