    "appopt.hint": "\u0627\u0644\u0628\u062F\u0621 \u0627\u0644\u062A\u0644\u0642\u0627\u0626\u064A \u0648\u0645\u0641\u0627\u062A\u064A\u062D \u0627\u0644\u0627\u062E\u062A\u0635\u0627\u0631 \u0627\u0644\u0639\u0627\u0645\u0629 \u0648\u0633\u0644\u0648\u0643 \u0634\u0631\u064A\u0637 \u0627\u0644\u0646\u0638\u0627\u0645 \u0648\u0627\u0644\u0646\u0633\u062E \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A \u062A\u062F\u064A\u0631\u0647\u0627 \u0639\u0645\u0644\u064A\u0629 \u0633\u0637\u062D \u0627\u0644\u0645\u0643\u062A\u0628 \u2014 \u062A\u0639\u0631\u0636 \u0635\u0641\u062D\u0629 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0647\u0630\u0647 \u062D\u0627\u0644\u062A\u0647\u0627 \u0627\u0644\u062D\u0642\u064A\u0642\u064A\u0629\u060C \u0648\u064A\u062D\u0627\u0643\u064A\u0647\u0627 \u0645\u0639\u0627\u064A\u0646\u0629 \u0627\u0644\u0645\u062A\u0635\u0641\u062D \u0628\u0623\u0645\u0627\u0646\u0629.",
    "appopt.loading": "\u062C\u0627\u0631\u064D \u0642\u0631\u0627\u0621\u0629 \u062A\u0641\u0636\u064A\u0644\u0627\u062A \u0627\u0644\u062A\u0637\u0628\u064A\u0642\u2026",
    "appopt.autostart": "\u0627\u0644\u0628\u062F\u0621 \u0645\u0639 \u0648\u064A\u0646\u062F\u0648\u0632",
    "appopt.autostartHint": "\u062A\u0634\u063A\u064A\u0644 MEMENTO \u062A\u0644\u0642\u0627\u0626\u064A\u0627\u064B \u0639\u0646\u062F \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644 (\u0645\u062E\u0641\u064A\u0627\u064B \u0641\u064A \u0634\u0631\u064A\u0637 \u0627\u0644\u0646\u0638\u0627\u0645). \u064A\u0639\u0645\u0644 \u0645\u0639 exe \u0627\u0644\u0645\u062D\u0645\u0648\u0644 \u0623\u064A\u0636\u0627\u064B \u2014 \u0625\u0630\u0627 \u0646\u0642\u0644\u062A \u0627\u0644\u0645\u0644\u0641 \u0623\u0648 \u063A\u064A\u0651\u0631\u062A \u0627\u0633\u0645\u0647\u060C \u0623\u0648\u0642\u0641 \u0647\u0630\u0627 \u0627\u0644\u062E\u064A\u0627\u0631 \u062B\u0645 \u0641\u0639\u0651\u0644\u0647 \u0645\u0631\u0629 \u0648\u0627\u062D\u062F\u0629 \u0644\u0625\u0639\u0627\u062F\u0629 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u062C\u062F\u064A\u062F",
    "appopt.autostartUnsupported": "\u0627\u0644\u0628\u062F\u0621 \u0627\u0644\u062A\u0644\u0642\u0627\u0626\u064A \u064A\u0639\u0645\u0644 \u0641\u064A \u062A\u0637\u0628\u064A\u0642 \u0648\u064A\u0646\u062F\u0648\u0632 \u0627\u0644\u0645\u0639\u0628\u0623 \u0641\u0642\u0637 (\u0628\u0645\u0627 \u0641\u064A \u0630\u0644\u0643 exe \u0627\u0644\u0645\u062D\u0645\u0648\u0644) \u2014 \u063A\u064A\u0631 \u0645\u062A\u0627\u062D \u0641\u064A \u0648\u0636\u0639 \u0627\u0644\u062A\u0637\u0648\u064A\u0631/\u0627\u0644\u0645\u062A\u0635\u0641\u062D",
