    "appopt.hotkeyConnHint": "Ctrl+Alt+C \u2014 \u062A\u0628\u062F\u064A\u0644 \u0627\u0644\u0627\u062A\u0635\u0627\u0644 \u0627\u0644\u062D\u0627\u0644\u064A \u0645\u0646 \u0623\u064A \u0645\u0643\u0627\u0646",
    "appopt.hotkeyStolen": "\u0645\u0637\u0644\u0648\u0628 \u062A\u0634\u063A\u064A\u0644\u0647\u060C \u0644\u0643\u0646 \u0628\u0631\u0646\u0627\u0645\u062C\u0627\u064B \u0622\u062E\u0631 \u064A\u0633\u062A\u062E\u062F\u0645 \u0647\u0630\u0627 \u0627\u0644\u062A\u0631\u0643\u064A\u0628",
    "appopt.hotkeyNoConfig": "\u0644\u0645 \u064A\u062A\u0645 \u0627\u062E\u062A\u064A\u0627\u0631 \u0625\u0639\u062F\u0627\u062F \u0628\u0639\u062F \u2014 \u0627\u062E\u062A\u0631 \u0648\u0627\u062D\u062F\u0627\u064B \u0645\u0646 \u0635\u0641\u062D\u0629 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0623\u0648\u0644\u0627\u064B",
    "appopt.hotkeyAether": "\u062A\u064F\u062F\u0627\u0631 \u062C\u0644\u0633\u0629 Aether \u0645\u0646 \u062A\u0628\u0648\u064A\u0628\u0647\u0627 \u0627\u0644\u062E\u0627\u0635",
    "appopt.backup": "\u0646\u0633\u062E \u0627\u062D\u062A\u064A\u0627\u0637\u064A / \u0627\u0633\u062A\u0639\u0627\u062F\u0629",
    "appopt.backupHint": "\u0645\u0644\u0641 JSON \u0648\u0627\u062D\u062F \u064A\u0636\u0645 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0648\u0627\u0644\u0645\u062C\u0645\u0648\u0639\u0627\u062A \u0648\u0627\u0644\u062E\u064A\u0627\u0631\u0627\u062A",
    "appopt.backupExport": "\u062A\u0635\u062F\u064A\u0631 \u0645\u0644\u0641 \u0627\u0644\u0646\u0633\u062E\u0629 \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0629",
    "appopt.backupImport": "\u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u0645\u0646 \u0645\u0644\u0641 \u0627\u0644\u0646\u0633\u062E\u0629 \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0629",
    "appopt.backupImportConfirm": "\u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u0647\u0630\u0647 \u0627\u0644\u0646\u0633\u062E\u0629 \u0648\u0627\u0633\u062A\u0628\u062F\u0627\u0644 \u0643\u0644 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0627\u0644\u062D\u0627\u0644\u064A\u0629 ({n} \u0639\u0646\u0635\u0631\u0627\u064B)\u061F \u0633\u064A\u064F\u0639\u0627\u062F \u062A\u062D\u0645\u064A\u0644 \u0627\u0644\u062A\u0637\u0628\u064A\u0642.",
    "appopt.backupExported": "\u062A\u0645 \u0625\u0646\u0634\u0627\u0621 \u0645\u0644\u0641 \u0627\u0644\u0646\u0633\u062E\u0629 \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0629",
    "appopt.backupRestored": "\u062A\u0645\u062A \u0627\u0644\u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u2014 \u062C\u0627\u0631\u064D \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u062A\u062D\u0645\u064A\u0644\u2026",
    "appopt.backupBad": "\u0645\u0644\u0641 \u0627\u0644\u0646\u0633\u062E\u0629 \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A\u0629 \u063A\u064A\u0631 \u0635\u0627\u0644\u062D",
    "set.closeToTray": "\u0627\u0644\u0625\u063A\u0644\u0627\u0642 \u0625\u0644\u0649 \u0634\u0631\u064A\u0637 \u0627\u0644\u0646\u0638\u0627\u0645",
    "set.closeToTrayHint": "\u064A\u0646\u0642\u0644 \u0632\u0631 \u0627\u0644\u0625\u063A\u0644\u0627\u0642 MEMENTO \u0625\u0644\u0649 \u0634\u0631\u064A\u0637 \u0627\u0644\u0646\u0638\u0627\u0645 \u0648\u064A\u0628\u0642\u064A VPN \u0645\u062A\u0635\u0644\u0627\u064B \u2014 \u0623\u064A\u0642\u0648\u0646\u0629 \u0627\u0644\u0634\u0631\u064A\u0637 \u062A\u0639\u064A\u062F \u0627\u0644\u0646\u0627\u0641\u0630\u0629. \u0623\u0648\u0642\u0641 \u0647\u0630\u0627 \u0627\u0644\u062E\u064A\u0627\u0631 \u0644\u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u062A\u0637\u0628\u064A\u0642 \u0639\u0646\u062F \u0625\u063A\u0644\u0627\u0642 \u0627\u0644\u0646\u0627\u0641\u0630\u0629",
    "set.killSwitch": "\u0645\u0641\u062A\u0627\u062D \u0627\u0644\u0625\u063A\u0644\u0627\u0642 \u0627\u0644\u0637\u0627\u0631\u0626 (Kill switch)",
    "set.killSwitchHint": "\u062D\u0645\u0627\u064A\u0629 \u0627\u0644\u0641\u0634\u0644 \u0627\u0644\u0645\u063A\u0644\u0642: \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062A\u0634\u063A\u064A\u0644\u060C \u0643\u0644 \u0645\u0631\u0629 \u064A\u0646\u0642\u0637\u0639 \u0641\u064A\u0647\u0627 \u0627\u0644\u0646\u0641\u0642 (\u0642\u0637\u0639 \u064A\u062F\u0648\u064A \u0623\u0648 \u0627\u0646\u0647\u064A\u0627\u0631 \u0627\u0644\u0646\u0648\u0627\u0629) \u064A\u064F\u0642\u0641\u0644 \u0627\u0644\u0648\u0643\u064A\u0644 \u0627\u0644\u0646\u0638\u0627\u0645\u064A \u0639\u0644\u0649 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u064A\u062A 127.0.0.1:9\u060C \u0641\u062A\u0641\u0642\u062F \u0627\u0644\u062A\u0637\u0628\u064A\u0642\u0627\u062A \u0627\u0644\u062A\u0627\u0628\u0639\u0629 \u0644\u0644\u0648\u0643\u064A\u0644 \u0627\u0644\u0646\u0638\u0627\u0645\u064A \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0628\u062F\u0644\u0627\u064B \u0645\u0646 \u062A\u0633\u0631\u064A\u0628 \u0639\u0646\u0648\u0627\u0646 IP \u0627\u0644\u062D\u0642\u064A\u0642\u064A. \u0627\u0644\u062A\u0633\u0644\u064A\u062D \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u0627\u0646\u0642\u0637\u0627\u0639 \u064A\u062D\u062C\u0628 \u0641\u0648\u0631\u0627\u064B. \u0641\u064A \u0648\u0636\u0639 \u062C\u0647\u0627\u0632 VPN (TUN) \u064A\u0642\u0648\u062F \u0646\u0641\u0633 \u0627\u0644\u0645\u0641\u062A\u0627\u062D \u062D\u0627\u0644\u0629 \u0627\u0644\u0627\u062D\u062A\u0641\u0627\u0638: \u0627\u0644\u062C\u0644\u0633\u0629 \u0627\u0644\u0645\u0633\u0644\u0651\u062D\u0629 \u062A\u062D\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0644\u0646\u0641\u0642 \u0639\u0646\u062F \u0645\u0648\u062A \u0627\u0644\u0645\u0646\u0628\u0639 (\u0625\u0639\u0627\u062F\u0629 \u0627\u062A\u0635\u0627\u0644)\u060C \u0648\u0625\u0630\u0627 \u062A\u0648\u0642\u0641 \u0627\u0644\u0645\u0633\u0627\u0639\u062F \u0639\u0646 \u0627\u0644\u0625\u0628\u0644\u0627\u063A \u064A\u064F\u062D\u062C\u0628 \u0627\u0644\u0648\u0643\u064A\u0644 \u0627\u0644\u0646\u0638\u0627\u0645\u064A \u0628\u062F\u0644\u0627\u064B \u0645\u0646 \u0630\u0644\u0643. \u0648\u0627\u0644\u062E\u0631\u0648\u062C \u0645\u0646 \u0627\u0644\u062A\u0637\u0628\u064A\u0642 \u064A\u0639\u064A\u062F \u0627\u0644\u0627\u062A\u0635\u0627\u0644 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u062F\u0627\u0626\u0645\u0627\u064B. \u0627\u0644\u0646\u0637\u0627\u0642 \u0628\u0635\u062F\u0642: \u064A\u063A\u0637\u064A \u0641\u0642\u0637 \u0627\u0644\u062A\u0637\u0628\u064A\u0642\u0627\u062A \u0627\u0644\u0645\u0644\u062A\u0632\u0645\u0629 \u0628\u0627\u0644\u0648\u0643\u064A\u0644 \u0627\u0644\u0646\u0638\u0627\u0645\u064A \u0644\u0648\u064A\u0646\u062F\u0648\u0632 \u2014 \u0647\u0630\u0627 \u062D\u062C\u0628 \u0639\u0644\u0649 \u0645\u0633\u062A\u0648\u0649 \u0627\u0644\u0648\u0643\u064A\u0644\u060C \u0648\u0644\u064A\u0633 \u062C\u062F\u0627\u0631 \u062D\u0645\u0627\u064A\u0629.",
    "set.sectionWindow": "\u0627\u0644\u0646\u0627\u0641\u0630\u0629 \u0648\u0628\u062F\u0621 \u0627\u0644\u062A\u0634\u063A\u064A\u0644",
    "set.sectionHotkeys": "\u0645\u0641\u0627\u062A\u064A\u062D \u0627\u0644\u0627\u062E\u062A\u0635\u0627\u0631 \u0627\u0644\u0639\u0627\u0645\u0629",
