    "donate.subtitle": "\u0625\u0630\u0627 \u0643\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062C \u0642\u062F \u0633\u0647\u0651\u0644 \u062D\u064A\u0627\u062A\u0643 \u0642\u0644\u064A\u0644\u0627\u064B \u0648\u0633\u0627\u0639\u062F\u0643 \u0639\u0644\u0649 \u0627\u0644\u0627\u062A\u0635\u0627\u0644\u060C \u064A\u0645\u0643\u0646\u0643 \u0645\u0633\u0627\u0639\u062F\u062A\u064A \u0641\u064A \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0645\u0632\u064A\u062F \u0645\u0646 \u0627\u0644\u0645\u064A\u0632\u0627\u062A \u0623\u0648 \u0628\u0646\u0627\u0621 \u062A\u0637\u0628\u064A\u0642\u0627\u062A \u0645\u0645\u0627\u062B\u0644\u0629 \u0644\u0643.",
