    "contact.dedication": "\u0623\u064F\u0647\u062F\u064A \u0647\u0630\u0627 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062C \u0625\u0644\u0649 \u0622\u0647\u0648 (A Who). \u0639\u0644\u0649 \u0627\u0644\u0631\u063A\u0645 \u0645\u0646 \u0623\u0646\u0646\u064A \u0641\u0642\u062F\u062A\u0647\u0627\u060C \u0625\u0644\u0627 \u0623\u0646\u0647\u0627 \u0639\u0644\u0645\u062A\u0646\u064A \u0645\u0627 \u0647\u0648 \u0627\u0644\u062D\u0628. \u0625\u0630\u0627 \u0623\u0631\u062F\u062A\u060C \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0627\u0646\u0636\u0645\u0627\u0645 \u0625\u0644\u0649 \u0642\u0646\u0627\u0629 \u0627\u0644\u062A\u0644\u063A\u0631\u0627\u0645\u060C \u0631\u0628\u0645\u0627 \u062A\u062A\u0633\u0644\u0649 \u0642\u0644\u064A\u0644\u0627\u064B.",
