    "aether.noTrafficStats": "\u0646\u0648\u0627\u0629 Aether \u0644\u0627 \u062A\u0648\u0641\u0651\u0631 \u0623\u064A \u0648\u0627\u062C\u0647\u0629 \u0644\u0625\u062D\u0635\u0627\u0621\u0627\u062A \u0627\u0644\u062D\u0631\u0643\u0629 \u2014 \u0627\u0644\u0633\u0631\u0639\u0629 \u0627\u0644\u0644\u062D\u0638\u064A\u0629 \u0648\u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u062D\u0631\u0643\u0629 \u063A\u064A\u0631 \u0645\u062A\u0627\u062D\u064A\u0646 \u0644\u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639 \u0645\u0646 \u0627\u0644\u0627\u062A\u0635\u0627\u0644.",
    "aether.trafficNote": "\u0646\u0648\u0627\u0629 Aether \u0644\u0627 \u062A\u0648\u0641\u0631 \u0623\u064A \u0648\u0627\u062C\u0647\u0629 \u0644\u0625\u062D\u0635\u0627\u0621\u0627\u062A \u0627\u0644\u062D\u0631\u0643\u0629\u060C \u0644\u0630\u0627 \u062A\u0628\u0642\u0649 \u0627\u0644\u0639\u062F\u0651\u0627\u062F\u0627\u062A \u0627\u0644\u062A\u0631\u0627\u0643\u0645\u064A\u0629 \u0639\u0644\u0649 \u0635\u0641\u0631 \u0623\u062B\u0646\u0627\u0621 \u0627\u062A\u0635\u0627\u0644 Aether (\u062A\u0628\u0642\u0649 \u0627\u0644\u0633\u062C\u0644\u0627\u062A \u062D\u064A\u0629).",
    "aether.attribution": "Aether \u0645\u0634\u0631\u0648\u0639 \u0645\u0633\u062A\u0642\u0644 \u0645\u0646 CluvexStudio\u061B MEMENTO \u063A\u0644\u0627\u0641 \u063A\u064A\u0631 \u0631\u0633\u0645\u064A \u0648\u0644\u0627 \u0639\u0644\u0627\u0642\u0629 \u0644\u0647 \u0628\u0645\u0624\u0644\u0641\u064A\u0647 \u0648\u0644\u0627 \u064A\u062D\u0638\u0649 \u0628\u062A\u0623\u064A\u064A\u062F\u0647\u0645\u0627.",
    "aether.updateTitle": "\u062A\u062D\u062F\u064A\u062B \u0646\u0648\u0627\u0629 Aether",
    "aether.updateHint": "\u062A\u062B\u0628\u064A\u062A \u0644\u0643\u0644 \u0625\u0635\u062F\u0627\u0631 (pin-per-version): \u0644\u0627 \u064A\u0645\u0643\u0646 \u062A\u062B\u0628\u064A\u062A \u0625\u0644\u0627 \u0627\u0644\u0625\u0635\u062F\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u062F\u0631\u062C\u0629 \u0641\u064A \u062C\u062F\u0648\u0644 \u0627\u0644\u062A\u062B\u0628\u064A\u062A \u0627\u0644\u062E\u0627\u0635 \u0628\u0647\u0630\u0627 \u0627\u0644\u0628\u0646\u0627\u0621\u060C \u0648\u064A\u064F\u062A\u062D\u0642\u0642 \u0645\u0646 sha256 \u0644\u0643\u0644 \u062A\u0646\u0632\u064A\u0644 \u0645\u0642\u0627\u0628\u0644 \u0630\u0644\u0643 \u0627\u0644\u062C\u062F\u0648\u0644 \u0642\u0628\u0644 \u0643\u062A\u0627\u0628\u0629 \u0623\u064A \u0645\u0644\u0641. \u0644\u0627 \u064A\u0641\u062D\u0635 \u0627\u0644\u062A\u0637\u0628\u064A\u0642 \u0628\u0646\u0641\u0633\u0647 \u0623\u0628\u062F\u0627\u064B \u2014 \u064A\u062D\u062F\u062B \u0627\u0644\u0641\u062D\u0635 \u0641\u0642\u0637 \u0639\u0646\u062F\u0645\u0627 \u062A\u0646\u0642\u0631 \u0627\u0644\u0632\u0631\u060C \u0648\u0628\u062F\u0648\u0646 \u0641\u062D\u0635 \u064A\u0628\u0642\u0649 \u0627\u0644\u062A\u062B\u0628\u064A\u062A \u0627\u0644\u0645\u0631\u0641\u0642 \u0641\u0639\u0627\u0644\u0627\u064B. \u0645\u0633\u0627\u0631 \u0627\u0644\u0641\u062D\u0635/\u0627\u0644\u062A\u0646\u0632\u064A\u0644 \u0644\u0627 \u064A\u0644\u0645\u0633 \u0623\u064A \u0625\u0639\u062F\u0627\u062F \u0646\u0638\u0627\u0645 \u0623\u0628\u062F\u0627\u064B.",
