    "aether.updateUnpinnedNewer": "\u0627\u0644\u0625\u0635\u062F\u0627\u0631 {version} \u0645\u062A\u0648\u0641\u0631 \u0641\u064A \u0627\u0644\u0645\u0635\u062F\u0631 \u0627\u0644\u0631\u0633\u0645\u064A \u0644\u0643\u0646\u0647 \u063A\u064A\u0631 \u0645\u062B\u0628\u064E\u0651\u062A \u0641\u064A \u0647\u0630\u0627 \u0627\u0644\u0628\u0646\u0627\u0621 \u2014 \u062D\u062F\u0651\u062B MEMENTO \u0646\u0641\u0633\u0647 \u0623\u0648\u0644\u0627\u064B. \u0644\u0646 \u064A\u064F\u0646\u0632\u064E\u0651\u0644 \u0623\u064A \u0634\u064A\u0621 \u0647\u0646\u0627.",
