    "set.appUpdateSteps": "\u062A\u062D\u062F\u064A\u062B \u064A\u062F\u0648\u064A (\u0645\u062D\u0645\u0648\u0644): 1. \u0623\u063A\u0644\u0642 MEMENTO \u062A\u0645\u0627\u0645\u0627\u064B. 2. \u0646\u0632\u0651\u0644 \u0627\u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u062D\u0645\u0648\u0644 \u0627\u0644\u062C\u062F\u064A\u062F \u0645\u0646 \u0635\u0641\u062D\u0629 \u0627\u0644\u0625\u0635\u062F\u0627\u0631\u0627\u062A. 3. \u0627\u0633\u062A\u0628\u062F\u0644 \u0627\u0644\u0645\u062C\u0644\u062F/exe \u0627\u0644\u0642\u062F\u064A\u0645 \u0628\u0627\u0644\u062C\u062F\u064A\u062F. 4. \u0634\u063A\u0651\u0644 MEMENTO \u2014 \u062A\u064F\u062D\u0641\u0638 \u062A\u0641\u0636\u064A\u0644\u0627\u062A\u0643 \u0648\u0627\u0644\u0646\u0648\u0649.",
