    "tab.liveconn": "\u0627\u0644\u0627\u062A\u0635\u0627\u0644 \u0627\u0644\u062D\u064A",
    "updateCenter.title": "\u0645\u0631\u0643\u0632 \u0627\u0644\u062A\u062D\u062F\u064A\u062B",
    "updateCenter.desc": "\u062A\u062D\u062F\u064A\u062B \u0628\u0646\u0642\u0631\u0629 \u0648\u0627\u062D\u062F\u0629 \u0644\u0644\u0646\u0648\u0649 \u0627\u0644\u0645\u062F\u0645\u062C\u0629. \u064A\u064F\u062A\u062D\u0642\u0642 \u0645\u0646 \u0627\u0644\u062A\u0646\u0632\u064A\u0644 \u0623\u0648\u0644\u0627\u064B (\u064A\u062C\u0628 \u0623\u0646 \u064A\u0639\u0645\u0644 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u062C\u062F\u064A\u062F \u0648\u064A\u064F\u0639\u0644\u0646 \u0646\u0633\u062E\u062A\u0647)\u060C \u062B\u0645 \u064A\u064F\u062B\u0628\u064E\u0651\u062A \u0628\u0634\u0643\u0644 \u0622\u0645\u0646 \u2014 \u0648\u064A\u064F\u062D\u062A\u0641\u0638 \u0628\u0627\u0644\u0646\u0633\u062E\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u0643\u0645\u0644\u0641 .bak \u0644\u0644\u062A\u0631\u0627\u062C\u0639. \u064A\u0628\u0642\u0649 MEMENTO \u0645\u062A\u0648\u0627\u0641\u0642\u0627\u064B \u0645\u0639 \u0623\u064A \u0625\u0635\u062F\u0627\u0631 \u0645\u0646 \u0627\u0644\u0646\u0648\u0649: \u0639\u0646\u062F\u0645\u0627 \u064A\u062D\u0630\u0641 \u0646\u0648\u0627\u0629 \u062C\u062F\u064A\u062F\u0629 \u0645\u064A\u0632\u0629\u060C \u064A\u064F\u0643\u064A\u064E\u0651\u0641 \u0627\u0644\u0625\u0639\u062F\u0627\u062F \u062A\u0644\u0642\u0627\u0626\u064A\u0627\u064B.",
    "updateCenter.phase.checking": "\u062C\u0627\u0631\u064D \u0641\u062D\u0635 \u0623\u062D\u062F\u062B \u0625\u0635\u062F\u0627\u0631\u2026",
