    "updateCenter.err.verifyVersion": "\u0646\u0633\u062E\u0629 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u062A\u0646\u0641\u064A\u0630\u064A \u0627\u0644\u0645\u064F\u0646\u0632\u0651\u0644 \u062A\u062E\u062A\u0644\u0641 \u0639\u0646 \u0627\u0644\u0645\u062A\u0648\u0642\u0639\u0629.",
    "updateCenter.err.blockedRunning": "\u0627\u0644\u0646\u0648\u0627\u0629 \u0642\u064A\u062F \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u2014 \u0627\u0641\u0635\u0644 \u0623\u0648\u0644\u0627\u064B \u062B\u0645 \u0623\u0639\u062F \u0627\u0644\u062A\u062B\u0628\u064A\u062A.",
    "updateCenter.err.apply": "\u0641\u0634\u0644 \u0627\u0644\u062A\u062B\u0628\u064A\u062A \u2014 \u062A\u0645\u062A \u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u0627\u0644\u0646\u0633\u062E\u0629 \u0627\u0644\u0633\u0627\u0628\u0642\u0629.",
    "updateCenter.err.noAsset": "\u0644\u0627 \u064A\u0648\u062C\u062F \u0645\u0644\u0641 \u0642\u0627\u0628\u0644 \u0644\u0644\u062A\u0646\u0632\u064A\u0644 \u0644\u0647\u0630\u0647 \u0627\u0644\u0645\u0646\u0635\u0629.",
    "liveconn.title": "\u0627\u0644\u0627\u062A\u0635\u0627\u0644 \u0627\u0644\u062D\u064A",
    "liveconn.desc": "\u0643\u0644 \u062A\u0637\u0628\u064A\u0642 \u064A\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0627\u0644\u0622\u0646 \u2014 \u0645\u0642\u0627\u0628\u0633 \u062D\u0642\u064A\u0642\u064A\u0629 \u0645\u0646 \u0646\u0638\u0627\u0645 \u0627\u0644\u062A\u0634\u063A\u064A\u0644\u060C \u062A\u062A\u062D\u062F\u062B \u0645\u0628\u0627\u0634\u0631\u0629. \u0627\u0646\u0642\u0631 \u0639\u0644\u0649 \u0623\u064A \u062A\u0637\u0628\u064A\u0642 \u0644\u0631\u0624\u064A\u0629 \u0646\u0642\u0627\u0637\u0647 \u0627\u0644\u0646\u0647\u0627\u0626\u064A\u0629 \u0627\u0644\u0628\u0639\u064A\u062F\u0629.",
    "googleside.title": "GOOGLE SIDE \u2014 MHRV",
